/**
 * Writes docs/COVERAGE.md from each week's overview checklist, so the
 * coverage table can never drift from the content. `--check` fails if the
 * file on disk is out of date.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { LEVELS } from '../src/content/schema'
import { loadWeeks, ROOT } from './load'

const out: string[] = [
  '# Coverage',
  '',
  'Generated by `npm run coverage` from each week\'s overview checklist (`week.yaml`). Do not edit by hand.',
  '',
  'Each row is a concept the real exercise needs, with the lessons that teach it, the drills that practise it',
  'and the part of the pre-PPT exercise that uses it. `npm run check` fails if any concept lacks a lesson or',
  'a drill, if any id here does not exist, or if this file is out of date.',
  '',
]

for (const { id, content: c } of loadWeeks()) {
  const lessons = c.groups.flatMap((g) => g.lessons)
  const title = (lid: string) => lessons.find((l) => l.id === lid)?.title ?? lid
  const part = (pid: string) => c.prePpt.parts.find((p) => p.id === pid)?.title ?? pid
  const cell = (s: string) => s.replace(/\|/g, '\\|')

  out.push(`## ${id}`, '')
  out.push('| Concept the real exercise needs | Lesson(s) | Drill ids | Pre-PPT part |', '| --- | --- | --- | --- |')
  for (const item of c.overview.checklist) {
    out.push(
      `| **${cell(item.concept)}**<br>${cell(item.detail)} | ${item.lessons.map(title).map(cell).join('<br>')} | ${item.drills
        .map((d) => '`' + d + '`')
        .join(', ')} | ${item.parts.map(part).map(cell).join('<br>') || '–'} |`,
    )
  }

  const used = new Set(c.overview.checklist.flatMap((i) => i.drills))
  const unlisted = c.drills.filter((d) => !used.has(d.id)).map((d) => '`' + d.id + '`')
  const n = (t: string) => c.drills.filter((d) => d.type === t).length
  out.push(
    '',
    '### Summary',
    '',
    `- Concepts: ${c.overview.checklist.length}, each with at least one lesson and one drill.`,
    `- Lessons: ${lessons.length} (${c.groups.map((g) => `${g.title} ${g.lessons.length}`).join(', ')}), every one linked from at least one concept.`,
    `- Runnable lesson examples: ${lessons.flatMap((l) => l.blocks).filter((b) => b.kind === 'example').length}; inline check questions: ${
      lessons.flatMap((l) => l.blocks).filter((b) => b.kind === 'check').length
    }.`,
    `- Drills: ${c.drills.length} (${LEVELS.map((l) => `${l.title} ${c.drills.filter((d) => d.level === l.id).length}`).join(', ')}).`,
    `- Drill types: write-a-function ${n('write')}, predict-the-output ${n('predict')}, fill-in-the-blank ${n('fill')}, multiple choice ${n('mc')}.`,
    `- Drills cited in the table: ${used.size} of ${c.drills.length}.${unlisted.length ? ` Not cited (general practice): ${unlisted.join(', ')}.` : ''}`,
    `- Pre-PPT exercise: ${c.prePpt.parts.length} parts (${c.prePpt.parts.filter((p) => p.kind === 'core').length} core, ${
      c.prePpt.parts.filter((p) => p.kind === 'extension').length
    } extension), ${c.prePpt.tests.length} tests (${c.prePpt.parts.map((p) => `${p.title}: ${c.prePpt.tests.filter((t) => t.part === p.id).length}`).join('; ')}).`,
    '',
  )
}

const file = join(ROOT, 'docs/COVERAGE.md')
const text = out.join('\n')
if (process.argv.includes('--check')) {
  if (!existsSync(file) || readFileSync(file, 'utf8') !== text) {
    console.error('docs/COVERAGE.md is out of date: run `npm run coverage`')
    process.exit(1)
  }
  console.log('coverage doc: up to date')
} else {
  writeFileSync(file, text)
  console.log('wrote docs/COVERAGE.md')
}
